class Solution {
  public List<Integer> zigzagTraversal(int[][] grid) {
    List<Integer> ans = new ArrayList<>();
    int step = 0;
    for (int i = 0; i < grid.length; i++) {
      int n = grid[i].length;
      for (int t = 0; t < n; t++) {
        int j = i % 2 == 0 ? t : n - 1 - t;
        if (step++ % 2 == 0) ans.add(grid[i][j]);
      }
    }
    return ans;
  }
}
